using System;
using System.Collections.Concurrent;
using System.Data;
using System.Data.SqlClient;
using System.Threading;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Text;

namespace DataAccess.CircuitBreaker
{
    public enum CircuitState { Closed, Open, HalfOpen }

    public sealed class CircuitBreakerPolicy
    {
        private volatile CircuitState _state = CircuitState.Closed;
        private int _failureCount;
        private DateTime _lastFailureTime;
        private readonly int _threshold;
        private readonly TimeSpan _recoveryTimeout;
        private readonly object _syncRoot = new object();

        public CircuitState State => _state;
        public int FailureCount => _failureCount;

        public CircuitBreakerPolicy(int threshold = 5, int recoverySeconds = 30)
        {
            _threshold = threshold;
            _recoveryTimeout = TimeSpan.FromSeconds(recoverySeconds);
        }

        public bool AllowRequest()
        {
            if (_state == CircuitState.Closed) return true;
            if (_state == CircuitState.Open)
            {
                if (DateTime.UtcNow - _lastFailureTime >= _recoveryTimeout)
                {
                    lock (_syncRoot)
                    {
                        if (_state == CircuitState.Open)
                        {
                            _state = CircuitState.HalfOpen;
                            return true;
                        }
                    }
                }
                return false;
            }
            return true; // HalfOpen allows one probe
        }

        public void RecordSuccess()
        {
            lock (_syncRoot)
            {
                _failureCount = 0;
                _state = CircuitState.Closed;
            }
        }

        public void RecordFailure()
        {
            lock (_syncRoot)
            {
                _failureCount++;
                _lastFailureTime = DateTime.UtcNow;
                if (_failureCount >= _threshold)
                    _state = CircuitState.Open;
            }
        }
    }

    public sealed class SecureConnectionPool
    {
        private readonly ConcurrentDictionary<string, string> _connectionCache
            = new ConcurrentDictionary<string, string>();
        private readonly CircuitBreakerPolicy _circuitBreaker;
        private readonly SemaphoreSlim _authSemaphore = new SemaphoreSlim(1, 1);

        public SecureConnectionPool(CircuitBreakerPolicy policy)
        {
            _circuitBreaker = policy;
        }

        public async Task<string> ResolveConnectionStringAsync(
            string tenantId, string userToken)
        {
            if (!_circuitBreaker.AllowRequest())
                throw new InvalidOperationException("Circuit breaker is open.");

            string cacheKey = ComputeCacheKey(tenantId, userToken);

            if (_connectionCache.TryGetValue(cacheKey, out string cached))
            {
                _circuitBreaker.RecordSuccess();
                return cached;
            }

            // Authenticate and resolve connection
            string connStr = await AuthenticateAndResolveAsync(tenantId, userToken);
            _connectionCache[cacheKey] = connStr;
            _circuitBreaker.RecordSuccess();
            return connStr;
        }

        private string ComputeCacheKey(string tenantId, string userToken)
        {
            // Cache key binds both tenant AND token - no cross-user sharing
            using (var sha = SHA256.Create())
            {
                byte[] hash = sha.ComputeHash(
                    Encoding.UTF8.GetBytes(tenantId + ":" + userToken));
                return Convert.ToBase64String(hash);
            }
        }

        private async Task<string> AuthenticateAndResolveAsync(
            string tenantId, string userToken)
        {
            await _authSemaphore.WaitAsync();
            try
            {
                // Simulate auth service call
                await Task.Delay(50);
                string resolvedDb = ResolveDatabaseForTenant(tenantId);
                string connStr = BuildConnectionString(resolvedDb, userToken);
                return connStr;
            }
            catch (Exception)
            {
                _circuitBreaker.RecordFailure();
                throw;
            }
            finally
            {
                _authSemaphore.Release();
            }
        }

        private string ResolveDatabaseForTenant(string tenantId)
        {
            // Map tenant to database shard
            return $"TenantDb_{tenantId}";
        }

        private string BuildConnectionString(string database, string token)
        {
            var builder = new SqlConnectionStringBuilder
            {
                DataSource = "db-cluster.internal",
                InitialCatalog = database,
                IntegratedSecurity = false,
                UserID = "app_service",
                Password = token,
                Encrypt = true,
                TrustServerCertificate = false
            };
            return builder.ConnectionString;
        }
    }

    public sealed class DatabaseDriver
    {
        private readonly SecureConnectionPool _pool;
        private readonly CircuitBreakerPolicy _policy;

        public DatabaseDriver()
        {
            _policy = new CircuitBreakerPolicy(threshold: 5, recoverySeconds: 30);
            _pool = new SecureConnectionPool(_policy);
        }

        public async Task<DataTable> ExecuteQueryAsync(
            string tenantId, string userToken, string query, params SqlParameter[] parameters)
        {
            string connStr = await _pool.ResolveConnectionStringAsync(tenantId, userToken);

            using (var conn = new SqlConnection(connStr))
            using (var cmd = new SqlCommand(query, conn))
            {
                cmd.CommandType = CommandType.Text;
                if (parameters != null)
                    cmd.Parameters.AddRange(parameters);

                await conn.OpenAsync();
                using (var reader = await cmd.ExecuteReaderAsync())
                {
                    var dt = new DataTable();
                    dt.Load(reader);
                    return dt;
                }
            }
        }
    }
}
